import pandas as pd
import numpy as np

# Load datasets
DATASET_PATH = 'chunks_csv/moran_local_2022_transport.csv'
df = pd.read_csv(DATASET_PATH)
adj = pd.read_csv(ADJACENCY_PATH)

# Clean strings
df['borough'] = df['borough'].str.strip()
adj['borough'] = adj['borough'].str.strip()
adj['neighbor'] = adj['neighbor'].str.strip()

# Build symmetric adjacency dictionary
adj_dict = {}
for b in df['borough']:
    adj_dict[b] = set()
for _, row in adj.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b not in adj_dict:
        adj_dict[b] = set()
    if n not in adj_dict:
        adj_dict[n] = set()
    adj_dict[b].add(n)
    adj_dict[n].add(b)

# Prepare values and z-scores
df = df.sort_values('borough').reset_index(drop=True)
boroughs = df['borough'].tolist()
values = df['Transport_value'].values
mean_val = values.mean()
z = values - mean_val
z_dict = {b: z[i] for i, b in enumerate(boroughs)}

# Compute observed Local Moran's I (row-standardized)
n = len(boroughs)
m2 = np.sum(z**2) / n

obs_stats = {}
for b in boroughs:
    neighbors = [nbr for nbr in adj_dict[b] if nbr in z_dict]
    if len(neighbors) == 0:
        obs_stats[b] = 0.0
    else:
        lag = np.mean([z_dict[nbr] for nbr in neighbors])
        obs_stats[b] = (z_dict[b] * lag) / m2

# Permutation test with 1000 shuffles
np.random.seed(42)
n_perm = 1000
perm_stats = {b: np.zeros(n_perm) for b in boroughs}

for i in range(n_perm):
    perm_z = np.random.permutation(z)
    perm_z_dict = {boroughs[j]: perm_z[j] for j in range(n)}
    for b in boroughs:
        neighbors = [nbr for nbr in adj_dict[b] if nbr in perm_z_dict]
        if len(neighbors) == 0:
            perm_stats[b][i] = 0.0
        else:
            lag = np.mean([perm_z_dict[nbr] for nbr in neighbors])
            perm_stats[b][i] = (perm_z_dict[b] * lag) / m2

# Compute one-tailed upper p-values
results = []
for b in boroughs:
    obs = obs_stats[b]
    count = np.sum(perm_stats[b] >= obs)
    p_val = (count + 1) / (n_perm + 1)
    results.append({
        'borough': b,
        'z': z_dict[b],
        'obs': obs,
        'p': p_val
    })

# Identify significant HH and LL spots
hh_spots = []
ll_spots = []
for r in results:
    if r['obs'] > 0 and r['p'] < 0.05:
        if r['z'] > 0:
            hh_spots.append(r)
        elif r['z'] < 0:
            ll_spots.append(r)

# Print reasoning and values
print("=== Local Spatial Autocorrelation Analysis ===")
print(f"Global mean transport energy use: {mean_val:.4f}")
print(f"Variance term m2 = sum(z^2)/n: {m2:.4f}")
print(f"Permutation shuffles: {n_perm}")

print("\nSignificant Hot Spots (HH) - high value surrounded by high values:")
if hh_spots:
    for r in hh_spots:
        print(f"  {r['borough']}: Local Moran's I = {r['obs']:.6f}, p-value = {r['p']:.6f}")
else:
    print("  None")

print("\nSignificant Cold Spots (LL) - low value surrounded by low values:")
if ll_spots:
    for r in ll_spots:
        print(f"  {r['borough']}: Local Moran's I = {r['obs']:.6f}, p-value = {r['p']:.6f}")
else:
    print("  None")

print("\nAll boroughs for reference:")
for r in sorted(results, key=lambda x: x['borough']):
    flag = ""
    if r['obs'] > 0 and r['p'] < 0.05:
        flag = "HH" if r['z'] > 0 else "LL"
    print(f"  {r['borough']}: z={r['z']:.4f}, I={r['obs']:.6f}, p={r['p']:.4f} {flag}")

# Build final answer line
spots = []
for r in hh_spots:
    spots.append(f"{r['borough']} (HH, LocalMoranI={r['obs']:.6f})")
for r in ll_spots:
    spots.append(f"{r['borough']} (LL, LocalMoranI={r['obs']:.6f})")

if spots:
    final_answer = "FINAL ANSWER: " + ", ".join(spots)
else:
    final_answer = "FINAL ANSWER: none"

print(final_answer)
